using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer accepts navigation values
        // or mutable expressions. Use a fixed seed value instead of DateTime.UtcNow.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; }  }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---
class CosmosDbContext : DbContext
{
    public DbSet<Document> Documents => Set<Document>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "MyDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Document>(b =>
        {
            b.ToContainer("Documents");
            b.HasPartitionKey(d => d.PartitionKey);
            b.HasNoDiscriminator();

            // EF Core 9 breaking change: Cosmos DB discriminator property renamed
            // from "Discriminator" to "$type". For existing documents that already
            // store "Discriminator", opt back in to the old name:
            b.HasDiscriminator<string>("Discriminator");
        });
    }

    // EF Core 9 breaking change: Synchronous I/O on Cosmos DB now throws by default.
    // Use async methods (ToListAsync, FirstOrDefaultAsync, etc.) instead.
    public async Task<List<Document>> GetDocumentsAsync(string partitionKey)
    {
        // WRONG (throws in EF Core 9):
        //   return Documents.Where(d => d.PartitionKey == partitionKey).ToList();
        // CORRECT:
        return await Documents
            .Where(d => d.PartitionKey == partitionKey)
            .ToListAsync();
    }
}

class Document
{
    public string Id { get; set; } = default!;
    public string PartitionKey { get; set; } = default!;
    public string Content { get; set; } = default!;
}

